mapper.insert:
insert into PTL_SEC_POSITION_DETAIL (PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, TRADE_ID, HODING_TYPE, CDATE, AMOUNT, CCY, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.TRADE_ID,targetTable.HODING_TYPE, #{batchDate,jdbcType=DATE}, SUM(targetTable.AMOUNT), targetTable.CCY,'system', null, sysdate, 'system', sysdate FROM ( SELECT PORTFOLIO_ID, NVL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, TRADE_ID, HODING_TYPE, CCY ,AMOUNT FROM PTL_SEC_POSITION_DETAIL WHERE HODING_TYPE IN (#{POSITION_TYPE_05,jdbcType=VARCHAR},#{POSITION_TYPE_06,jdbcType=VARCHAR}) and CDATE = #{lastDate,jdbcType=DATE}
and (
)
union all SELECT PORTFOLIO_ID, NVL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, TRADE_ID, HODING_TYPE, CCY, AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE HODING_TYPE IN (#{POSITION_TYPE_05,jdbcType=VARCHAR},#{POSITION_TYPE_06,jdbcType=VARCHAR}) and CDATE = #{batchDate,jdbcType=DATE}
and (
)
) targetTable GROUP BY targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.TRADE_ID, targetTable.HODING_TYPE, targetTable.CCY

insert into PTL_SEC_POSITION (PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, CDATE, AMOUNT, CCY, FACE_VALUE, P_FINPROD_ID, INV_AIM, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, #{batchDate,jdbcType=DATE}, SUM(targetTable.AMOUNT), targetTable.CCY, null, null, targetTable.INV_AIM, 'system', null, sysdate, 'system', sysdate FROM ( SELECT PORTFOLIO_ID, NVL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, AMOUNT, CCY, NVL(INV_AIM, '999999') as INV_AIM, HODING_TYPE FROM PTL_SEC_POSITION WHERE HODING_TYPE != #{POSITION_TYPE_01,jdbcType=VARCHAR} and CDATE = #{lastDate,jdbcType=DATE}
and (
)
union all SELECT PORTFOLIO_ID, NVL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, sum(AMOUNT) as AMOUNT, CCY, NVL(INV_AIM, '999999') as INV_AIM, HODING_TYPE FROM PTL_SEC_POSITION_FLOW WHERE HODING_TYPE != #{POSITION_TYPE_01,jdbcType=VARCHAR} and CDATE = #{batchDate,jdbcType=DATE}
and (
)
GROUP BY PORTFOLIO_ID, NVL(SEC_ACCT_ID, '999999'), FINPROD_ID, BRANCH, CCY, NVL(INV_AIM, '999999'), HODING_TYPE ) targetTable group by targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, targetTable.CCY, targetTable.INV_AIM

mapper.select:
select t.finprod_id finprodId,t.share_amt shareAmt,t.yield,t.ps from trd_product_deal t left JOIN trd_product_deal_add tpda on t.TRADE_ID=tpda.TRADE_ID left JOIN fin_product_type fpt on t.finprod_id=fpt.finprod_id and t.branch=fpt.branch where t.finprod_id=#{finprodId}
AND (tpda.PORTFOLIO_ID IN
null) OR tpda.PORTFOLIO_ID in (
#{item}
and to_date(#{date},'yyyy-MM-dd')=t.TRADE_DATE and fpt.type_8='F01'and t.trade_status='01'and t.is_cancel='N' and t.ps in('T01','T02') order by t.UPDATE_TIME asc

select t.pos_amount posAmount ,t.cost_rate costRate,t.FAIRE_PRICE fairePrice from  ASSET_TARGET_DB  t  where t.cdate=to_date(#{date},'yyyy-MM-dd')
and t.finprod_id=#{finprodId}

    and t.IS_PERNE= #{pass}

and rownum=1

mapper.insert:
insert into ptl_sec_position (portfolio_id, sec_acct_id, finprod_id, branch, inv_aim, hoding_type, cdate, amount, ccy, p_finprod_id, face_value, create_user, create_dept, create_time, update_user, update_time) select temp.portfolio_id, temp.sec_acct_id, 'XN_PRODID999' as finprod_id, temp.branch, '999999' as inv_aim, #{POSITION_TYPE_03} as hoding_type, #{batchDate,jdbcType=DATE} as cdate, sum(temp.amount) amount, 'CNY' ccy, null p_finprod_id, null face_value, 'system' create_user, null create_dept, cast (sysdate as timestamp) create_time, 'system' update_user, cast (sysdate as timestamp) update_time from (
select temp.portfolio_id, temp.sec_acct_id, detail.branch,
sum((case when temp.ps = 'T68' then detail.amt else -1 * detail.amt end) * nvl(fscr.scale, 1) * nvl(mzData.mzValue, 100) / 100 ) as amount
from trd_stasec_flow temp inner join trd_stasec_flow_detail detail on temp.seqno = detail.seqno left join fin_stdsec_converse_radio fscr on detail.finprod_id = fscr.finprod_id and fscr.vdate = #{batchDate,jdbcType=DATE}
left join ( SELECT t1.FINPROD_ID, t1.BRANCH, 100 - NVL(SUM(NVL(t1.PRIN_AMT, 0)), 0) as mzValue from FIN_CASH_PLAN t1 WHERE t1.FINPROD_TYPE2 = 'F01' and t1.CASH_TYPE in ('02', '03') and t1.MDATE <= #{batchDate,jdbcType=DATE} group by t1.FINPROD_ID, t1.BRANCH ) mzData on detail.FINPROD_ID = mzData.FINPROD_ID and detail.BRANCH = mzData.BRANCH
where temp.cdate <= #{batchDate,jdbcType=DATE}
and (
)
group by temp.portfolio_id, temp.sec_acct_id, detail.branch union all select ptl_cpf.portfolio_id, ptl_cpf.sec_acct_id, ptl_cpf.branch, sum(ptl_cpf.amount) as amount from ptl_sec_position_flow ptl_cpf where ptl_cpf.finprod_id = 'XN_PRODID999'
and (
)
and ptl_cpf.hoding_type = #{POSITION_TYPE_03} and ptl_cpf.trade_id not in (select ee.entrust_id from etr_entrust ee where ee.ps in ('T68', 'T69') union select tsf.seqno from trd_stasec_flow tsf) group by ptl_cpf.portfolio_id, ptl_cpf.sec_acct_id, ptl_cpf.branch) temp group by temp.portfolio_id, temp.sec_acct_id, temp.branch

